@model oblique_isolation_model {
  version:0; length-unit:mm;
  /* 원본 XYZ: two oblique sheets and an independent weighted reference Curve. */
  @surface #oblique_a { type:nurbs; degree-u:1; degree-v:1;
    knots-u:[0,0,1,1]; knots-v:[0,0,1,1];
    control-points:[[[-12,-8,4],[-12,4,10]],[[-2,-8,6],[-2,4,12]]];
    weights:[[1,1.25],[1.5,1]]; }
  /* This sibling must retain every source byte after a selected edit. */
  @surface #oblique_b { type:nurbs; degree-u:1; degree-v:1;
    knots-u:[0,0,1,1]; knots-v:[0,0,1,1];
    control-points:[[[3,-8,14],[3,4,10]],[[13,-8,18],[13,4,14]]];
    weights:[[1,2],[1.5,1]]; }
  @curve #oblique_reference { type:nurbs; degree:1; knots:[0,0,1,1];
    control-points:[[-10,-12,2],[10,-12,16]]; weights:[1,1.5]; }
  /* End: complete original three-object Model, never extracted for display. */
}
